===== hook =====
#!/bin/bash
# Deploy main and dev branches to Nginx web roots after push.
set -e

REPO_DIR="/git/project"
ZERO="0000000000000000000000000000000000000000"

while read oldrev newrev refname; do
    # Skip branch deletions
    if [ "$newrev" = "$ZERO" ]; then
        continue
    fi

    case "$refname" in
        refs/heads/main)
            dest="/var/www/html"
            ;;
        refs/heads/dev)
            dest="/var/www/dev"
            ;;
        *)
            continue
            ;;
    esac

    # Clean deploy directory contents (keep the directory itself) and extract
    # the snapshot of the pushed commit.
    shopt -s dotglob nullglob
    rm -rf "$dest"/*
    shopt -u dotglob nullglob
    mkdir -p "$dest"
    git --git-dir="$REPO_DIR" archive "$newrev" | tar -x -C "$dest"
done

exit 0

